css:
:root {
  --rv-accent: oklch(0.48 0.22 264);
  --rv-accent-soft: oklch(0.48 0.22 264 / 0.12);
  --rv-bg: #FAFAFA;
  --rv-bg-chart: oklch(1 0 0);
  --rv-bg-elev: oklch(0.9769 0.0109 274.9);
  --rv-block-gap: 5rem;
  --rv-brand: oklch(0.48 0.22 264);
  --rv-chart-ink: oklch(0 0 0);
  --rv-density: 1.25;
  --rv-down: oklch(0.55 0.19 27);
  --rv-font-display: Space Grotesk, Inter, sans-serif;
  --rv-font-mono: Geist Mono, JetBrains Mono, ui-monospace, monospace;
  --rv-font-text: Geist, Inter, system-ui, sans-serif;
  --rv-font-ui: Geist, Inter, system-ui, sans-serif;
  --rv-hold: oklch(0.55 0.12 70);
  --rv-ink: oklch(0 0 0);
  --rv-ink-faint: oklch(0.5456 0.0327 268.08);
  --rv-ink-soft: oklch(0.3313 0.0195 260.65);
  --rv-line-base: 1.65;
  --rv-link: oklch(0.48 0.22 264);
  --rv-measure: 42rem;
  --rv-radius-m: 4px;
  --rv-radius-s: 12px;
  --rv-report-max-width: 880px;
  --rv-rule: oklch(0.8635 0.0277 267.5);
  --rv-rule-soft: oklch(0.9399 0.0141 268.49);
  --rv-shadow-float: 0 2px 8px oklch(0 0 0 / 0.12);
  --rv-size-base: 18px;
  --rv-size-display: 50px;
  --rv-size-h1: 40px;
  --rv-size-h2: 30px;
  --rv-size-h3: 22px;
  --rv-size-small: 15px;
  --rv-up: oklch(0.52 0.13 150);
}
@media (max-width: 640px) {
:root {
  --rv-block-gap: 3rem;
  --rv-size-base: 17px;
  --rv-size-display: 38px;
  --rv-size-h1: 33px;
  --rv-size-h2: 28px;
  --rv-size-h3: 21px;
  --rv-size-small: 14px;
}
}
:root{color-scheme:light}
:root{--rv-motion-duration:640ms;--rv-motion-easing:cubic-bezier(0.25,0.8,0.25,1);--rv-motion-stagger:50ms;--rv-motion-distance:10px;--rv-motion-block:fade-up}
.rv-report__body blockquote{font-style:italic}
.rv-callout{border-top-width:1px}
.rv-report__title{letter-spacing:-0.035em}
.rv-chart{border:2px solid var(--rv-ink);padding:1rem 1.25rem}
.rv-chart.rv-chart--expanded{border:0;background:none;border-radius:0}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
